"""ENet Event class."""

from __future__ import annotations
from typing import Optional
from .peer import Peer
from .packet import Packet
from .constants import (
    EVENT_TYPE_NONE,
    EVENT_TYPE_CONNECT,
    EVENT_TYPE_DISCONNECT,
    EVENT_TYPE_RECEIVE,
    EVENT_TYPE_DISCONNECT_TIMEOUT,
)

_TYPE_NAMES = {
    EVENT_TYPE_NONE: "NONE",
    EVENT_TYPE_CONNECT: "CONNECT",
    EVENT_TYPE_DISCONNECT: "DISCONNECT",
    EVENT_TYPE_RECEIVE: "RECEIVE",
    EVENT_TYPE_DISCONNECT_TIMEOUT: "DISCONNECT_TIMEOUT",
}


class Event:
    """An event generated by enet_host_service() or check_events()."""

    def __init__(
        self,
        event_type: int = EVENT_TYPE_NONE,
        peer: Optional[Peer] = None,
        channel_id: int = 0,
        data: int = 0,
        packet: Optional[Packet] = None,
    ) -> None:
        self.type = int(event_type)
        self.peer = peer
        self.channel_id = int(channel_id)
        self.data = int(data)
        self.packet = packet

    @property
    def channelID(self) -> int:
        """Channel on which event arrived (pyenet alias)."""
        return self.channel_id

    @property
    def type_name(self) -> str:
        """Human-readable event type string."""
        return _TYPE_NAMES.get(self.type, f"UNKNOWN({self.type})")

    def __repr__(self) -> str:
        parts = [f"type={self.type_name}"]
        if self.peer is not None:
            parts.append(f"peer={self.peer.id}")
        if self.channel_id != 0:
            parts.append(f"channel={self.channel_id}")
        if self.data != 0:
            parts.append(f"data={self.data}")
        if self.packet is not None:
            parts.append(f"packet={self.packet!r}")
        return f"Event({', '.join(parts)})"
